t.script:

function getCsrfToken() {
    var cookieValue = document.cookie
        .split('; ')
        .find(function(row) { return row.startsWith('csrf_token='); });
    return cookieValue ? cookieValue.split('=')[1] : '';
}
document.addEventListener('DOMContentLoaded', function() {
    var loginBtn = document.getElementById('login-btn');
    if (loginBtn) {
        loginBtn.addEventListener('click', function() {
            var email = document.getElementById('email').value;
            var password = document.getElementById('password').value;
            fetch('/max/grades/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': getCsrfToken()
                },
                body: JSON.stringify({email: email, password: password})
            })
            .then(function(r) { return r.json(); })
            .then(function(result) {
                if (result.error) {
                    document.getElementById('error-msg').textContent = result.error;
                    document.getElementById('error-msg').classList.remove('d-none');
                } else {
                    window.location.href = '/max/grades/dashboard';
                }
            });
        });
    }
});


function getCsrfToken() {
    var cookieValue = document.cookie
        .split('; ')
        .find(function(row) { return row.startsWith('csrf_token='); });
    return cookieValue ? cookieValue.split('=')[1] : '';
}
document.addEventListener('DOMContentLoaded', function() {
    var logoutBtn = document.getElementById('logout-btn');
    if (logoutBtn) {
        logoutBtn.addEventListener('click', function() {
            window.location.href = '/max/grades/logout';
        });
    }
    document.querySelectorAll('[data-module-id]').forEach(function(el) {
        el.addEventListener('click', function() {
            var moduleId = this.getAttribute('data-module-id');
            if (moduleId === 'schedule') {
                window.location.href = '/max/grades/lessons';
            } else if (moduleId === 'grades') {
                window.location.href = '/max/grades/lessons';
            }
        });
    });
});


function getCsrfToken() {
    var cookieValue = document.cookie
        .split('; ')
        .find(function(row) { return row.startsWith('csrf_token='); });
    return cookieValue ? cookieValue.split('=')[1] : '';
}
function loadLessons() {
    var date = document.getElementById('date-picker').value;
    var facultyId = document.getElementById('faculty-filter') ? document.getElementById('faculty-filter').value : '';
    var url = '/max/grades/api/lessons?date=' + date;
    if (facultyId) url += '&faculty_id=' + facultyId;
    fetch(url, {
        method: 'GET',
        headers: {'Content-Type': 'application/json', 'X-CSRF-TOKEN': getCsrfToken()}
    })
    .then(function(r) { return r.json(); })
    .then(function(result) {
        var html = '';
        if (result.lessons && result.lessons.length) {
            result.lessons.forEach(function(l) {
                var timing = l.timing || '';
                var header = timing + ' | ' + l.subject + ' | ' + l.batch;
                html += '<button class="list-group-item list-group-item-action open-lesson" data-lesson-id="' + l.id + '">' +
                    '<div><small class="text-muted">' + header + '</small></div>' +
                    '<div><strong>' + (l.faculty || '') + '</strong></div>' +
                    '</button>';
            });
        } else {
            html = '<p class="text-muted">Нет занятий</p>';
        }
        document.getElementById('lessons-list').innerHTML = html;
        document.querySelectorAll('.open-lesson').forEach(function(btn) {
            btn.addEventListener('click', function() {
                window.location.href = '/max/grades/lesson/' + this.getAttribute('data-lesson-id');
            });
        });
    });
}
document.addEventListener('DOMContentLoaded', function() {
    var today = new Date().toISOString().split('T')[0];
    document.getElementById('date-picker').value = today;
    loadLessons();
    document.getElementById('date-picker').addEventListener('change', loadLessons);
    var facultyFilter = document.getElementById('faculty-filter');
    if (facultyFilter) facultyFilter.addEventListener('change', loadLessons);
    document.getElementById('back-btn').addEventListener('click', function() {
        window.location.href = '/max/grades/dashboard';
    });
});


function getCsrfToken() {
    var cookieValue = document.cookie
        .split('; ')
        .find(function(row) { return row.startsWith('csrf_token='); });
    return cookieValue ? cookieValue.split('=')[1] : '';
}
function fillGradeSelects() {
    document.querySelectorAll('.grade-select').forEach(function(select) {
        var html = '<option value="">-</option>';
        [5,4,3,2].forEach(function(v) {
            html += '<option>&nbsp;&nbsp;' + v + '</option>';
        });
        select.innerHTML = html;
    });
}
function saveGrades() {
    var grades = [];
    document.querySelectorAll('.student-row').forEach(function(row) {
        var selects = row.querySelectorAll('.grade-select');
        var attendSelect = row.querySelector('.attend-select');
        grades.push({
            student_id: parseInt(row.dataset.studentId),
            attendance_type_id: attendSelect ? (attendSelect.value || false) : false,
            grade_1: selects[0] ? (selects[0].value || null) : null,
            grade_2: selects[1] ? (selects[1].value || null) : null,
            grade_3: selects[2] ? (selects[2].value || null) : null
        });
    });
    var lessonId = window.location.pathname.match(/\/max\/grades\/lesson\/(\d+)/);
    if (!lessonId) return;
    fetch('/max/grades/lesson/' + lessonId[1] + '/grades', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': getCsrfToken()
        },
        body: JSON.stringify({grades: grades})
    })
    .then(function(r) { return r.json(); })
    .then(function(result) {
        alert(result.success ? 'Сохранено!' : 'Ошибка: ' + result.error);
    });
}
document.addEventListener('DOMContentLoaded', function() {
    fillGradeSelects();
    var saveBtn = document.getElementById('save-grades-btn');
    if (saveBtn) saveBtn.addEventListener('click', saveGrades);
    document.getElementById('back-to-lessons-btn').addEventListener('click', function() {
        window.location.href = '/max/grades/lessons';
    });
});
